class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        if (list1 == null) return list2;
        if (list2 == null) return list1;

        if (list1.val <= list2.val) {
            // 谁小谁当头，剩下的继续合并
            list1.next = mergeTwoLists(list1.next, list2);
            return list1;
        } else {
            list2.next = mergeTwoLists(list1, list2.next);
            return list2;
        }
    }
}

class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        ListNode dummy = new ListNode(0);   // 虚拟头，省掉首节点的特殊处理
        ListNode tail = dummy;

        while (list1 != null && list2 != null) {
            if (list1.val <= list2.val) {
                tail.next = list1;
                list1 = list1.next;
            } else {
                tail.next = list2;
                list2 = list2.next;
            }
            tail = tail.next;
        }
        // 剩下那条本身有序，整段挂上即可，不用逐个接
        tail.next = (list1 != null) ? list1 : list2;
        return dummy.next;
    }
}

class Solution {
    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {
        if (list1 == null) return list2;
        if (list2 == null) return list1;

        // 定头：谁小谁当头的第一个节点
        ListNode head, cur, other;
        if (list1.val <= list2.val) {
            head = list1;
            cur = list1;
            other = list2;
        } else {
            head = list2;
            cur = list2;
            other = list1;
        }

        while (cur.next != null && other != null) {
            if (cur.next.val <= other.val) {
                cur = cur.next;          // 原链继续走下去
            } else {
                // 把 other 插到 cur 后面
                ListNode tmp = cur.next;
                cur.next = other;
                other = tmp;
                cur = cur.next;
            }
        }
        // cur 走到头了，剩下的整段接上
        if (cur.next == null) cur.next = other;

        return head;
    }
}
